// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    SimpleSuicide c;
    function setUp() public { c = new SimpleSuicide(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        bound(amount, 1, type(uint256).max);

        // fund the contract under test with the fuzzed amount
        vm.deal(address(c), amount);

        // the owner of C is whoever deployed it in setUp(), i.e. this test contract
        bool ok;
        vm.prank(address(this));
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a successful owner suicide always empties the contract's
        // balance (paid out to the caller). The mutant self-destructs to itself,
        // so the full fuzzed amount remains at address(c).
        assertTrue(ok && address(c).balance == 0, "suicide must drain contract balance");
    }
}
